53	  const runtime = v.validateStringOption(
54	    TopLevelOptions.runtime,
55	    options.runtime,
56	    "automatic",
57	  );
58	  const throwIfNamespace = v.validateBooleanOption(
59	    TopLevelOptions.throwIfNamespace,
60	    options.throwIfNamespace,
